package com.bank.frequency;

import java.util.*;
import java.util.logging.*;

public class MostFrequentDemo {
    private static final Logger log = Logger.getLogger("Frequency");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        FrequencyAnalyzer analyzer = new FrequencyAnalyzer();
        log.info(() -> "banking → " + analyzer.mostFrequent("banking")); // 'n' (×2)
        log.info(() -> "aabbb   → " + analyzer.mostFrequent("aabbb"));   // 'b' (×3)
    }
}

// ─── Would be in service/FrequencyAnalyzer.java ───
class FrequencyAnalyzer {
    Optional<Character> mostFrequent(String s) {
        Map<Character, Long> counts = s.chars()
            .mapToObj(c -> (char) c)
            .collect(java.util.stream.Collectors.groupingBy(
                ch -> ch, java.util.stream.Collectors.counting()));
        return counts.entrySet().stream()
            .max(Comparator.comparingLong(Map.Entry<Character, Long>::getValue) // by count
                .thenComparing(Map.Entry::getKey))                               // tie-break
            .map(Map.Entry::getKey);
    }
}
